const i={title:"TripReel - App Mappa Viaggio Animata | Creatore Video Highlights Viaggio",description:"Crea straordinari video highlights viaggio e video riepilogo viaggio con mappe animate. App gratuita mappa viaggio animata con animatore percorso viaggio e mappatura rotta globo 3D. Trasforma le tue foto in splendidi video animazione viaggio automaticamente. App mappa viaggio animata privacy-first, funziona offline.",keywords:"app mappa viaggio animata, app video highlights viaggio, app video riepilogo viaggio, app animatore percorso viaggio, app riepilogo viaggi, app mappa viaggio animata, app animazione rotta viaggio, app video mappa viaggio, app creatore storie viaggio, app animazione viaggio, app creatore video viaggio, app animazione volo, video viaggio automatico, animazione rotta volo, app animazione viaggio, animazione globo, app foto a video, highlights viaggio, app viaggio gratuita, creatore video offline, app viaggio privata, video rullino"},a={logoAlt:"Logo TripReel",appName:"TripReel",howItWorks:"Come funziona",video:"Video",features:"Funzionalità",theApp:"L'app"},e={badge:"Trasforma le foto in storie di viaggio",title1:"Il tuo rullino,",title2:"pienamente sfruttato",description:"TripReel è l'app definitiva per mappe viaggio animate che crea automaticamente splendidi video highlights viaggio e video riepilogo viaggio dalle posizioni delle tue foto. Guarda i tuoi percorsi prendere vita con il nostro animatore percorso viaggio che presenta straordinarie mappe percorso animate e rotte aeree attraverso un globo 3D, mentre i tuoi dati rimangono privati e sicuri.",secure:"100% sicuro",worksOffline:"Funziona offline",globeAlt:"Animazione del globo TripReel"},o={title:"Come funziona",subtitle:"Tre semplici passaggi per creare il tuo video di viaggio perfetto",step1:{title:"Consenti accesso alle foto",description:"Concedi a TripReel l'accesso alla tua libreria foto. L'app legge solo i metadati di posizione, nient'altro."},step2:{title:"Rilevamento automatico dei viaggi",description:"TripReel analizza i metadati di posizione e trova intelligentemente i tuoi viaggi in base a date e luoghi."},step3:{title:"Genera il tuo video",description:"Guarda il tuo viaggio svolgersi con il nostro animatore percorso viaggio su una splendida animazione del globo, creando straordinari video highlights viaggio pronti da condividere sui social media."}},t={title:"Vedi la magia in azione",subtitle:"Scopri come la nostra app mappa viaggio animata trasforma la tua libreria foto in straordinari video highlights viaggio e video riepilogo viaggio con mappe percorso animate",caption:"Ecco come può apparire il tuo video animazione viaggio finale con la nostra app animatore percorso viaggio"},r={title:"Tutto ciò di cui hai bisogno",subtitle:"Funzionalità potenti progettate per i viaggiatori moderni",twoTap:{title:"Video di viaggio con due tocchi",description:"Crea straordinari video highlights viaggio e video riepilogo viaggio dalla tua libreria foto con soli due tocchi usando la nostra app creatore video viaggio. Nessuna modifica necessaria."},smartTrip:{title:"Rilevamento intelligente dei viaggi",description:"L'app riepilogo viaggi trova e raggruppa automaticamente i tuoi viaggi analizzando date e metadati di posizione dalle tue foto per creare video highlights viaggio perfetti."},globe:{title:"Splendida animazione del globo",description:"Guarda il tuo viaggio prendere vita con il nostro animatore percorso viaggio che presenta uno straordinario globo 3D che mostra i tuoi percorsi viaggio animati e le rotte aeree in tutto il mondo in splendidi video mappa viaggio."},privacy:{title:"Privacy al primo posto",description:"L'app mappa viaggio animata elabora tutto sul tuo dispositivo. Le tue foto non escono mai dal tuo telefono. Crea video animazione viaggio completamente offline in modalità aereo."},customStyles:{title:"Stili personalizzati",description:"Scegli tra più stili di globo e personalizzazioni per i tuoi video animazione viaggio per adattarsi alla tua estetica e rendere ogni video mappa viaggio animata unico."},manualControl:{title:"Controllo manuale",description:"L'app animatore percorso viaggio ti permette di aggiungere manualmente viaggi completamente nuovi e personalizzare la tua animazione rotta viaggio se i servizi di localizzazione non erano abilitati sul tuo dispositivo."}},n={title:"Idee creative per i video",subtitle:"Lasciati ispirare da ciò che puoi creare con TripReel, la tua app creatore storie viaggio. Dai rapidi weekend alle avventure di un anno, crea straordinari video highlights viaggio e video riepilogo viaggio per ogni percorso.",description:"Che tu stia creando un'animazione mappa viaggio, documentando una rotta aerea con la nostra app animatore percorso viaggio, o realizzando un video app riepilogo viaggi di fine anno, TripReel rende facile trasformare i tuoi ricordi in video animazione viaggio condivisibili.",ideas:{yearRecap:{title:"Riepilogo viaggi 2025",description:"Crea automaticamente il tuo video riepilogo annuale dei viaggi 2025 con la nostra app video highlights viaggio"},europeRoadTrip:{title:"Viaggio in auto in Europa",description:"Mostra la tua avventura europea con la nostra app mappa viaggio animata e mappe percorso animate"},southeastAsia:{title:"Viaggio nel Sud-Est Asiatico",description:"Visualizza il tuo percorso zaino in spalla attraverso più paesi con la nostra app animatore percorso viaggio"},japanRail:{title:"Viaggio in treno in Giappone",description:"Crea video mappa viaggio dei tuoi percorsi in treno attraverso il Giappone con mappe viaggio animate"},crossCountry:{title:"Da costa a costa negli USA",description:"Trasforma il tuo road trip americano in un epico video animazione rotta viaggio con la nostra app animazione viaggio"},islandHopping:{title:"Tour tra le isole",description:"Mostra i tuoi viaggi da isola a isola con straordinarie animazioni 3D usando la nostra app creatore storie viaggio"},worldTour:{title:"Montaggio giro del mondo",description:"Combina più viaggi in un unico straordinario video viaggio globale con la nostra app mappa viaggio animata"},travelPlans:{title:"Piani di viaggio 2026",description:"Visualizza e pianifica le tue emozionanti avventure di viaggio per il 2026 con il nostro animatore percorso viaggio"},lifetimeTravel:{title:"Storia di viaggio di una vita",description:"Crea un video riepilogo viaggio che mostra tutti i tuoi viaggi di una vita con la nostra app riepilogo viaggi"},regionalExplorer:{title:"Esploratore regionale",description:"Traccia le tue avventure attraverso stati, province e regioni con la nostra app mappa viaggio animata"},festivalCircuit:{title:"Circuito dei festival",description:"Traccia il tuo viaggio tra festival musicali ed eventi con video rotta viaggio animati"},bikeRoutes:{title:"Le mie fughe in città",description:"Mostra tutte le tue fughe urbane con splendidi video mappa viaggio"}}},l={title:"L'app",subtitle:"Disponibile ora sull'App Store",alt1:"App Mappa Viaggio Animata - Crea video highlights viaggio automaticamente in secondi",alt2:"Animatore Percorso Viaggio - Usa i metadati di posizione delle tue foto per video riepilogo viaggio",alt3:"Rilevamento Viaggi - Raggruppa automaticamente i tuoi viaggi per video mappa viaggio animati",alt4:"Splendidi Video del Globo - Animazione del globo del tuo viaggio con la nostra app animazione viaggio",alt5:"Stili Personalizzati - Personalizza i tuoi video animazione rotta viaggio con più stili di globo"},p={comingSoon:"Prossimamente",androidTitle:"App Android in arrivo!",androidMessage:'La versione Android non è ancora disponibile ma lo sarà presto. Scrivimi a <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> e ti avviserò quando sarà pronta!',gotIt:"Capito!"},g={title:"Domande frequenti",subtitle:"Tutto quello che devi sapere su TripReel",q1:{question:"Posso usare questa app mappa viaggio animata completamente offline in modalità aereo?",answer:"Sì! Per gli utenti premium, l'app video highlights viaggio può essere utilizzata completamente offline in modalità aereo senza limitazioni. Per gli utenti non premium, alcune funzionalità sono supportate da pubblicità che potrebbero richiedere l'abilitazione temporanea di Internet, ma gli utenti premium possono creare video riepilogo viaggio completamente offline senza annunci."},q2:{question:"Come posso rimuovere la filigrana dai miei video animazione viaggio?",answer:"Molte persone chiedono quale app creatore video viaggio è stata utilizzata per creare questi video mappa viaggio animati. Dopo l'upgrade a premium, hai l'opzione di aggiungere una versione più piccola della filigrana (solo con il nome dell'app) o rimuoverla completamente dai tuoi video highlights viaggio se lo desideri."},q3:{question:"I dati delle mie foto sono sicuri e privati in questa app animatore percorso viaggio?",answer:"Assolutamente! L'app mappa viaggio animata legge solo i metadati di posizione dalle tue foto - non accediamo mai, archiviamo o trasmettiamo il contenuto effettivo delle foto. Tutta l'elaborazione dei video animazione viaggio avviene localmente sul tuo dispositivo e nessun dato lascia mai il tuo telefono. Puoi verificarlo creando video riepilogo viaggio in modalità aereo - funziona perfettamente offline!"},q4:{question:"E se le mie foto non hanno dati di posizione per l'animazione rotta viaggio?",answer:"Nessun problema! Se i servizi di localizzazione non erano abilitati quando hai scattato le foto, l'app creatore storie viaggio ti permette di creare manualmente viaggi e aggiungere posizioni tu stesso. L'animatore percorso viaggio ti dà il controllo completo per personalizzare la tua timeline di viaggio e creare splendidi video mappa viaggio animati anche senza dati GPS."},q5:{question:"Come rileva questa app riepilogo viaggi i miei viaggi automaticamente?",answer:"L'app mappa viaggio animata analizza i metadati di posizione e i timestamp dalle tue foto per identificare intelligentemente quando e dove hai viaggiato. Raggruppa posizioni e date vicine per rilevare automaticamente i tuoi viaggi e creare straordinari video highlights viaggio senza alcun lavoro manuale."},q6:{question:"Posso personalizzare l'aspetto dei miei video highlights viaggio?",answer:"Sì! La nostra app animazione viaggio ti permette di scegliere tra più stili di globo e personalizzare vari aspetti dei tuoi video mappa viaggio animati per adattarli alla tua estetica personale. Gli utenti premium ottengono l'accesso a stili di animazione percorso aggiuntivi, temi di mappe e opzioni di rotte aeree."},q7:{question:"Devo creare un account per usare questa app creatore video viaggio?",answer:"Nessun account richiesto! L'app animazione viaggio funziona immediatamente dopo il download. Non c'è registrazione, nessun login e nessuna informazione personale necessaria. Scarica semplicemente l'app mappa viaggio animata e inizia subito a creare i tuoi video rotta viaggio animati."},q8:{question:"Perché manca una posizione dal mio video mappa viaggio animata?",answer:"L'app animatore percorso viaggio può funzionare solo con i dati disponibili, quindi hai bisogno di almeno un paio di foto in quella posizione con dati GPS. Assicurati di aver abilitato i servizi di localizzazione quando eri lì. A volte una scarsa ricezione GPS può causare dati di posizione errati. Se la tua posizione non viene ancora visualizzata nel tuo video highlights viaggio, puoi aggiungere manualmente quella posizione da Panoramica viaggi > pulsante Modifica. Ti preghiamo di utilizzare Contatto per segnalare il problema."},q9:{question:"Dove posso condividere i miei video riepilogo viaggio e animazioni rotta viaggio?",answer:"Puoi condividere i tuoi video animazione viaggio su tutte le piattaforme social! La nostra app mappa viaggio animata consente diverse proporzioni (verticale, widescreen, cinema, quadrato) per i tuoi video mappa viaggio animati per adattarsi meglio a ogni piattaforma - perfetti per Instagram, TikTok, YouTube, Facebook e altro."},q10:{question:"Dove posso segnalare un bug?",answer:"Contattami direttamente a marian@qod.ee, spiegando brevemente qual è il problema."}},s={title:"Supporto via email",description:"Se hai feedback o riscontri problemi, non esitare a contattarmi direttamente a questo indirizzo email e leggerò e gestirò personalmente la tua richiesta il più rapidamente possibile. Grazie per aver utilizzato l'app!",close:"Chiudi"},d={default:{title:"🍪 Cookie",message:"Utilizziamo i cookie sul sito TripReel per migliorare la tua esperienza. Nessun dato personale raccolto.",accept:"Accetta",decline:"Rifiuta",details:"Dettagli"},theme:{title:"🍪 Cookie",message:"🌙 Per salvare la tua preferenza del tema, devi accettare i cookie essenziali sul sito TripReel. Senza di essi, la tua scelta del tema non può essere salvata.",accept:"Accetta",decline:"Rifiuta",details:"Dettagli"}},v={privacy:"Informativa sulla privacy dell'app",cookies:"Informativa sui cookie del sito",contact:"Contatto",cookiePreferences:"Preferenze cookie",madeWith:"Creato con",forTravelers:"per viaggiatori in tutto il mondo",copyright:"© {{year}} TripReel."},c={title:"Pronto a condividere il tuo viaggio?",description:"Scarica TripReel oggi e trasforma il tuo rullino in splendidi video highlights viaggio con la nostra app mappa viaggio animata che presenta l'animatore percorso viaggio e l'animazione rotta viaggio. Le tue avventure meritano di essere celebrate con straordinari video riepilogo viaggio.",features:"Download gratuito • Veloce e conveniente • Privacy garantita"},m={title:"Informazioni su TripReel",subtitle:"Creatore professionale video highlights viaggio e app animatore percorso viaggio",howItWorks:{title:"Come funziona la nostra app riepilogo viaggi",description:"L'app animazione viaggio utilizza algoritmi intelligenti per scansionare i dati GPS delle tue foto e rilevare automaticamente i tuoi viaggi. L'animatore percorso viaggio crea quindi animazioni rotta viaggio cinematiche e fluide che mostrano il tuo percorso attraverso città, paesi e continenti. Che tu stia creando un rapido video highlights viaggio del weekend o un video riepilogo viaggio di un anno, l'app mappa viaggio animata lo rende semplice."},customization:{title:"Personalizzazione estesa per i tuoi video animazione viaggio",description:"L'app creatore storie viaggio offre opzioni di personalizzazione di livello professionale per rendere i tuoi video mappa viaggio animati davvero unici:",features:{videoQuality:"Scegli tra 30 FPS, 60 FPS o premium 90 FPS per animazioni rotta viaggio fluide come seta nei tuoi video highlights viaggio",bitrate:"Regola la qualità video (bitrate) da normale ad alta per video mappa viaggio cristallini senza artefatti visivi",earthStyles:"Seleziona tra più stili di globo straordinari tra cui Realistico, Luci Notturne, Mappa Diurna e viste Satellitari per i tuoi video mappa viaggio animati",borders:"Attiva i confini dei paesi sul tuo animatore percorso viaggio con colori e spessore personalizzabili per una visualizzazione geografica migliorata",aspectRatios:"Crea video animazione viaggio in formati Verticale (9:16), Widescreen (16:9), Cinema (2.35:1) o Quadrato (1:1) perfetti per Instagram, TikTok, YouTube e altre piattaforme social",tripSpeed:"Controlla la velocità dell'animatore percorso viaggio tra le posizioni (fino a 3500 km/s) per creare video riepilogo viaggio dinamici o rilassati",pauseDuration:"Regola la durata della pausa in ogni posizione (0.5-5 secondi) per evidenziare destinazioni importanti nei tuoi video highlights viaggio",locationLabels:"Mostra etichette di Città, Regione e/o Paese sui tuoi video mappa viaggio animati per fornire contesto al tuo viaggio",pathDisplay:"Attiva se desideri mostrare tutti i percorsi di viaggio passati o solo il viaggio attuale nella tua animazione rotta viaggio"}}},u={meta:i,header:a,hero:e,howItWorks:o,videoSection:t,features:r,videoIdeas:n,screenshots:l,appStore:p,faq:g,contact:s,cookieBanner:d,footer:v,cta:c,about:m};export{m as about,p as appStore,s as contact,d as cookieBanner,c as cta,u as default,g as faq,r as features,v as footer,a as header,e as hero,o as howItWorks,i as meta,l as screenshots,n as videoIdeas,t as videoSection};
